const r = await tools.exec_command({cmd:"python3 - <<'PY'
import pandas as pd,numpy as np
from collections import Counter
from scipy.special import softmax
from experiment_utils import CLASSES,balanced_test_assignment
A=pd.read_csv('/tmp/test_model_probs.csv');B=pd.read_csv('/tmp/test_model_probs2.csv')
models={}
for D,names in [(A,['et','lgb','cat','svc']),(B,['lgb_sorted','lgb_full','lgb_full15','cat_sorted','cat_full','svc_full','xgb_full'])]:
 for n in names:models[n]=D[[n+'_'+c for c in CLASSES]].values

def centerlog(P,norm=False):
 L=np.log(np.clip(P,1e-8,1)); L-=L.mean(1,keepdims=True)
 if norm:L/=np.sqrt(np.mean(L*L))
 return L
families={
 'lgb':['lgb','lgb_sorted','lgb_full','lgb_full15'],
 'cat':['cat','cat_sorted','cat_full'],
 'svc':['svc','svc_full'],
 'xgb':['xgb_full'],
 'et':['et']}
FG={f:np.mean([centerlog(models[n],True) for n in ns],axis=0) for f,ns in families.items()}

def lab(score):return CLASSES[balanced_test_assignment(softmax(score,axis=1))]
cands={}
for f,L in FG.items():cands[f]=lab(L)
for name,w in {
 'LCX':[.4,.4,0,.2,0],
 'LCSX':[.35,.35,.15,.15,0],
 'LCSXE':[.32,.34,.14,.16,.04],
 'LC':[.5,.5,0,0,0],
 'CSX':[0,.5,.25,.25,0],
 'LCS':[.4,.4,.2,0,0],
 'all_equal':[.2,.2,.2,.2,.2],
}.items(): cands[name]=lab(sum(wi*FG[f] for wi,f in zip(w,families)))
# probability arithmetic family and global
FP={f:np.mean([models[n] for n in ns],axis=0) for f,ns in families.items()}
for name,w in {'aLCSX':[.35,.35,.15,.15,0],'aLCX':[.4,.4,0,.2,0],'aLC':[.5,.5,0,0,0]}.items():
 cands[name]=CLASSES[balanced_test_assignment(sum(wi*FP[f] for wi,f in zip(w,families)))]
print(pd.DataFrame([[np.mean(cands[a]==cands[b]) for b in cands]for a in cands],index=cands,columns=cands).round(3).to_string())
sel=['LCX','LCSX','LCSXE','LC','CSX','LCS','aLCSX','aLCX']
V=np.array([cands[x] for x in sel]); u=np.apply_along_axis(lambda x:len(set(x)),0,V)
print('consensus spread',Counter(u),'all candidate consensus',sum(u==1))
# family balanced votes support for chosen LCSX
base=cands['LCSX']; FL=np.array([cands[f] for f in families]); support=np.sum(FL==base,axis=0)
print('LCSX family support',Counter(support))
for i in np.where((u>1)|(support<3))[0]:print(i,A.id[i],base[i],'support',support[i],'alts',Counter(V[:,i]),'family',dict(zip(families,FL[:,i])))
# save candidate matrices for later
pd.DataFrame({'id':A.id,**cands}).to_csv('/tmp/candidate_labels.csv',index=False)
