const results = await Promise.all([
  tools.exec_command({cmd:"python3 -m pip install -q ucimlrepo pmlb",workdir:"/workspace",yield_time_ms:30000,max_output_tokens:20000}),
  tools.exec_command({cmd:"python3 - <<'PY'
import pandas as pd,numpy as np
from experiment_utils import CLASSES
A=pd.read_csv('/tmp/test_model_probs.csv');B=pd.read_csv('/tmp/test_model_probs2.csv')
mods={}
for D,names in [(A,['et','lgb','cat','svc']),(B,['lgb_sorted','lgb_full','lgb_full15','cat_sorted','cat_full','svc_full','xgb_full'])]:
 for n in names:mods[n]=D[[n+'_'+c for c in CLASSES]].values
for n,P in mods.items():print(n,dict(zip(CLASSES,np.bincount(P.argmax(1),minlength=6))),round(P.max(1).mean(),3))
# family normalized-log ensemble without quota
F={'lgb':['lgb','lgb_sorted','lgb_full','lgb_full15'],'cat':['cat','cat_sorted','cat_full'],'svc':['svc','svc_full'],'xgb':['xgb_full'],'et':['et']}
def logit(P):
